import test from "node:test";
import assert from "node:assert/strict";
import {mkdtempSync, mkdirSync, readFileSync, rmSync, writeFileSync} from "node:fs";
import {tmpdir} from "node:os";
import {join} from "node:path";
import {fileURLToPath} from "node:url";
import {spawnSync} from "node:child_process";
import {apply, planner} from "./replay.mjs";
import {publicationCalendar, projectCalendar} from "./utilization.mjs";

const catalog = {default: 5, studios: new Map([["orchid", 8], ["iris", 2]])};
const booking = (id, units, extra = {}) => ({
  service: "studio", action: "book", tenant: "orchid", day: "2025-04-02", id, units, ...extra
});
const operation = (action, extra) => ({service: "studio", action, ...extra});

function workspace(t) {
  const path = mkdtempSync(join(tmpdir(), "orchid-quota-"));
  t.after(() => rmSync(path, {recursive: true, force: true}));
  return path;
}

function cli(script, args, cwd) {
  return spawnSync(process.execPath, [fileURLToPath(new URL(script, import.meta.url)), ...args],
                   {cwd, encoding: "utf8"});
}

function successful(result) {
  assert.equal(result.status, 0, result.stderr);
  return JSON.parse(result.stdout);
}

test("Studio allocates per tenant/day, including defaults and quotas below the default", () => {
  const dispatch = planner(catalog);
  assert.deepEqual(dispatch(booking("first", 7)), {status: "booked", id: "first", remaining: 1});
  assert.deepEqual(dispatch(booking("too-many", 2)), {status: "full", id: "too-many", remaining: 1});
  assert.equal(dispatch(booking("last", 1)).remaining, 0);
  assert.equal(dispatch(booking("tomorrow", 8, {day: "2025-04-03"})).status, "booked");
  assert.equal(dispatch(booking("iris-large", 3, {tenant: "iris"})).status, "full");
  assert.equal(dispatch(booking("iris", 2, {tenant: "iris"})).remaining, 0);
  assert.equal(dispatch(booking("unknown-large", 6, {tenant: "unlisted"})).status, "full");
  assert.equal(dispatch(booking("unknown", 5, {tenant: "unlisted"})).remaining, 0);
  assert.equal(dispatch(booking("archive-large", 6, {service: "archive"})).status, "full");
  assert.equal(dispatch(booking("archive", 5, {service: "archive"})).remaining, 0);
});

test("identity, cancellation, imports and validation retain ledger semantics", () => {
  const dispatch = planner(catalog);
  const request = booking("first", 8);
  dispatch(request);
  assert.equal(dispatch(request).status, "replay");
  assert.equal(dispatch({...request, units: 7}).status, "conflict");
  assert.equal(dispatch(operation("cancel", {id: "first"})).status, "cancelled");
  assert.equal(dispatch(operation("cancel", {id: "first"})).status, "replay");
  assert.equal(dispatch(request).status, "cancelled");
  assert.equal(dispatch(booking("replacement", 8)).status, "booked");
  assert.deepEqual(dispatch(operation("usage", {tenant: "orchid", day: request.day})), {units: 8});
  assert.equal(dispatch(booking("backfill", 10, {action: "import", day: "2025-04-03"})).status, "imported");
  assert.equal(dispatch(booking("backfill", 10, {day: "2025-04-03"})).status, "replay");
  assert.deepEqual(dispatch(booking("over-import", 1, {day: "2025-04-03"})),
                   {status: "full", id: "over-import", remaining: 0});
  assert.equal(apply(dispatch, booking("invalid", 0)).status, "invalid");
  const summary = dispatch(operation("summary"));
  assert.equal(summary.events.filter(event => event.type === "booked").length, 3);
});

test("renewals inherit tenant and units while using the same admission and replay policy", () => {
  const dispatch = planner(catalog);
  dispatch(booking("first", 7));
  const renewal = operation("renew", {previous: "first", id: "renewed", day: "2025-05-02", tenant: "iris"});
  assert.deepEqual(dispatch(renewal), {status: "booked", id: "renewed", remaining: 1});
  assert.equal(dispatch(renewal).status, "replay");
  assert.equal(dispatch({...renewal, units: 6}).status, "conflict");
  assert.equal(dispatch({...renewal, id: "too-much", units: 2}).status, "full");
  dispatch(operation("cancel", {id: "renewed"}));
  assert.equal(dispatch(renewal).status, "cancelled");
  assert.equal(dispatch({...renewal, id: "replacement", units: 8}).status, "booked");
  dispatch(operation("cancel", {id: "first"}));
  assert.equal(dispatch({...renewal, id: "missing"}).status, "missing");
  assert.equal(dispatch({...renewal, previous: "absent"}).status, "missing");
  for (const [tenant, service] of [["unlisted", "studio"], ["orchid", "archive"], ["iris", "studio"]]) {
    const id = `${service}-${tenant}`;
    dispatch(booking(id, 1, {tenant, service}));
    const next = {...renewal, service, previous: id, id: `${id}-next`, units: tenant === "iris" ? 3 : 6};
    assert.equal(dispatch(next).status, "full");
    assert.equal(dispatch({...next, units: tenant === "iris" ? 2 : 5}).remaining, 0);
  }
});

function feed() {
  return {
    edition: "orchid-quota",
    window: {service: "studio", tenant: "orchid", from: "2025-04-02", through: "2025-04-03"},
    subscriptions: [{service: "studio", tenant: "orchid"}, {service: "studio", tenant: "iris"},
                    {service: "archive", tenant: "orchid"}],
    days: ["2025-04-01", "2025-04-02", "2025-04-03", "2025-04-04"],
    operations: [
      booking("prior", 6, {day: "2025-04-01"}),
      operation("renew", {previous: "prior", id: "renewed", day: "2025-04-02"}),
      booking("temporary", 2),
      operation("cancel", {id: "temporary"}),
      operation("cancel", {id: "prior"}),
      booking("other", 1, {tenant: "iris"}),
      booking("archive", 4, {service: "archive"})
    ]
  };
}

test("publication replays the full history before selecting audience and inclusive dates", () => {
  const source = feed();
  const rows = publicationCalendar(source, catalog);
  assert.deepEqual(rows, [
    {service: "studio", tenant: "orchid", day: "2025-04-02", edition: "orchid-quota", cap: 8, used: 6, available: 2},
    {service: "studio", tenant: "orchid", day: "2025-04-03", edition: "orchid-quota", cap: 8, used: 0, available: 8}
  ]);
  assert.deepEqual(rows, projectCalendar(source, catalog).filter(row =>
    row.service === "studio" && row.tenant === "orchid" && row.day >= source.window.from && row.day <= source.window.through));
  source.operations.push(booking("over-capacity", 10, {action: "import", day: "2025-04-03"}));
  assert.equal(publicationCalendar(source, catalog)[1].available, 0);
});

test("publish-calendar preserves unrelated cells, replaces selected cells, and is byte-idempotent", t => {
  const dir = workspace(t);
  const sourcePath = join(dir, "feed.json");
  const diaryPath = join(dir, "diary.json");
  const outside = [
    {service: "studio", tenant: "iris", day: "2025-04-02", edition: "signed", cap: 5, used: 2, available: 3},
    {service: "archive", tenant: "orchid", day: "2025-04-02", edition: "signed", cap: 5, used: 1, available: 4},
    {service: "studio", tenant: "orchid", day: "2025-04-01", edition: "signed", cap: 5, used: 2, available: 3},
    {service: "studio", tenant: "orchid", day: "2025-04-04", edition: "signed", cap: 5, used: 2, available: 3}
  ];
  writeFileSync(sourcePath, JSON.stringify(feed()));
  writeFileSync(diaryPath, JSON.stringify([...outside, {...outside[2], day: "2025-04-02"}]));
  const args = ["publish-calendar", sourcePath, diaryPath];
  assert.deepEqual(successful(cli("utilization.mjs", args, dir)), {edition: "orchid-quota", rows: 2});
  const published = readFileSync(diaryPath, "utf8");
  const rows = JSON.parse(published);
  assert.equal(rows.length, 6);
  assert.deepEqual(rows.slice(0, 4), outside);
  assert.equal(rows[4].used, 6);
  assert.equal(rows[5].used, 0);
  successful(cli("utilization.mjs", args, dir));
  assert.equal(readFileSync(diaryPath, "utf8"), published);
  for (const window of [null, {...feed().window, service: "unknown"}, {...feed().window, from: "2025-04-31"},
                        {...feed().window, from: "2025-04-04"}]) {
    writeFileSync(sourcePath, JSON.stringify({...feed(), window}));
    assert.notEqual(cli("utilization.mjs", args, dir).status, 0);
    assert.equal(readFileSync(diaryPath, "utf8"), published);
  }
});

test("desk-specific staging preserves the queue and is idempotent", t => {
  const dir = workspace(t);
  mkdirSync(join(dir, "fixtures"));
  const path = join(dir, "fixtures/release-queue.json");
  const previous = {release: "summer", service: "archive", default: 5, allocations: {}};
  writeFileSync(path, JSON.stringify([previous]));
  const args = ["stage", "orchid-quota", "studio"];
  const queue = successful(cli("replay.mjs", args, dir));
  assert.deepEqual(queue, [previous, {release: "orchid-quota", service: "studio", default: 5, allocations: {orchid: 8}}]);
  const once = readFileSync(path, "utf8");
  successful(cli("replay.mjs", args, dir));
  assert.equal(readFileSync(path, "utf8"), once);
  assert.notEqual(cli("replay.mjs", ["stage", "bad", "unknown"], dir).status, 0);
  assert.equal(readFileSync(path, "utf8"), once);
  assert.equal(successful(cli("replay.mjs", ["stage", "coordinated"], dir)).length, 4);
});
